'use strict';
const $ = id => document.getElementById(id);
const {products,applyCommand,total,lineTotal}=Billing;
const money=paise=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format(paise/100);
const dateLabel=iso=>new Date(iso).toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'});
let rows=[],previous=null,saved=false,billId=crypto.randomUUID(),createdAt=new Date().toISOString(),history=[];
function feedback(message,error=false){$('feedback').textContent=message;$('feedback').classList.toggle('error',error);}
try{const parsed=JSON.parse(localStorage.getItem('bolbill-sales-v1')||'[]');if(Array.isArray(parsed))history=parsed.filter(s=>s&&typeof s.id==='string'&&Array.isArray(s.rows)&&s.rows.every(r=>products.some(p=>p.id===r.id)&&Number.isInteger(r.qty)&&r.qty>0&&r.qty<=1000000&&Number.isInteger(r.price)&&r.price>=0)&&Number.isFinite(Date.parse(s.createdAt))&&['Cash','UPI','Unpaid'].includes(s.payment));}catch{feedback('Saved history could not be read. New bills still work.',true);}
try{const draft=JSON.parse(localStorage.getItem('bolbill-draft-v1')||'null');if(draft&&typeof draft.id==='string'&&Number.isFinite(Date.parse(draft.createdAt))&&Array.isArray(draft.rows)&&draft.rows.every(r=>products.some(p=>p.id===r.id)&&Number.isInteger(r.qty)&&r.qty>0&&r.qty<=1000000&&Number.isInteger(r.price)&&r.price>=0)){if(!history.some(s=>s.id===draft.id)){rows=draft.rows;billId=draft.id;createdAt=draft.createdAt;}}}catch{/* An unreadable draft must not prevent a fresh sale. */}
function persistDraft(){try{localStorage.setItem('bolbill-draft-v1',JSON.stringify({id:billId,createdAt,rows}));}catch{feedback('Draft is only in memory. Browser storage is unavailable; keep this tab open.',true);}}
function cell(tag,className,text){const el=document.createElement(tag);if(className)el.className=className;if(text!==undefined)el.textContent=text;return el;}
function render(){
  $('bill-number').textContent='BILL #'+billId.slice(0,6).toUpperCase();$('bill-date').textContent=dateLabel(createdAt);
  const target=$('bill-items');target.replaceChildren();
  if(!rows.length){const empty=cell('div','empty-receipt');empty.innerHTML='<svg viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="M8 5h16v23l-4-2-4 2-4-2-4 2V5Z"/><path d="M12 12h8m-8 5h6"/></svg>';empty.append(cell('strong','','Your next bill starts here.'),cell('span','','Speak a few items, or tap a product to get started.'));target.append(empty);}
  rows.forEach(row=>{const p=products.find(p=>p.id===row.id);const el=cell('div','bill-row'),details=cell('div'),name=cell('div','item-name',p.name);if(!saved){const remove=cell('button','remove-item','×');remove.setAttribute('aria-label','Remove '+p.name);remove.addEventListener('click',()=>{previous=rows.map(r=>({...r}));rows=rows.filter(r=>r.id!==p.id);persistDraft();render();feedback(p.name+' removed. Undo is available.');});name.append(remove);}details.append(name,cell('div','item-qty',(row.qty/1000)+' '+p.unit+' × '+money(row.price)));el.append(details,cell('div','item-amount',money(lineTotal(row))));target.append(el);});
  $('subtotal').textContent=$('total').textContent=money(total(rows));$('save-bill').disabled=!rows.length||saved;$('save-bill').firstChild.textContent=saved?'Bill saved ':'Confirm & save ';$('undo').disabled=!previous||saved;$('payment').disabled=saved;$('add-command').disabled=saved;$('command').disabled=saved;$('bill-status').textContent=saved?'Saved receipt':'Draft receipt';$('save-hint').textContent=saved?'Saved in this browser. Ready for the next customer.':'Check items and quantities before saving.';$('history-count').textContent=history.length;
}
function showView(view){document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==view+'-view');document.querySelectorAll('.nav-button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='history')renderHistory();}
function addProduct(p){if(saved){showView('sale');feedback('This bill is saved. Select New bill to start another.',true);return;}previous=rows.map(r=>({...r}));const r=rows.find(r=>r.id===p.id);if(r&&r.qty>=1000000){feedback('Quantity limit reached.',true);return;}if(r)r.qty+=1000;else rows.push({id:p.id,qty:1000,price:p.price});showView('sale');persistDraft();render();feedback(p.name+' added.');}
function renderHistory(){const list=$('history-list');list.replaceChildren();if(!history.length){list.append(cell('div','history-empty','No saved bills yet. Create a bill, review it, then select Confirm & save.'));return;}[...history].reverse().forEach(s=>{const row=cell('article','history-row'),info=cell('div');info.append(cell('h2','','Bill #'+s.id.slice(0,6).toUpperCase()),cell('p','',s.rows.map(r=>{const p=products.find(p=>p.id===r.id);return p.name+' · '+(r.qty/1000)+' '+p.unit;}).join(' / ')),cell('small','',dateLabel(s.createdAt)+' · '+s.payment));row.append(info,cell('strong','',money(total(s.rows))));list.append(row);});}
products.forEach(p=>{const chip=cell('button','product-chip',p.name.split(' · ')[0]);chip.addEventListener('click',()=>addProduct(p));$('quick-items').append(chip);const item=cell('article','catalogue-product');item.append(cell('h2','',p.name),cell('p','',p.english+' · '+money(p.price)+' / '+p.unit),cell('p','','Say: '+p.aliases[0]));const add=cell('button','secondary','Add 1 '+p.unit);add.addEventListener('click',()=>addProduct(p));item.append(add);$('catalogue').append(item);});
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.view)));$('see-products').addEventListener('click',()=>showView('products'));
document.querySelectorAll('[data-example]').forEach(b=>b.addEventListener('click',()=>{if(saved){feedback('Select New bill before adding another sale.',true);return;}$('command').value=b.dataset.example;$('command').focus();feedback('Example loaded. Select Add to bill to apply it.');}));
function submitCommand(){if(saved)return;try{const next=applyCommand($('command').value,rows);previous=rows.map(r=>({...r}));rows=next;persistDraft();render();$('command').value='';feedback('Bill updated. Check the receipt before saving.');}catch(e){feedback(e.message+' Bill unchanged.',true);}}
$('add-command').addEventListener('click',submitCommand);$('command').addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();submitCommand();}});
$('undo').addEventListener('click',()=>{if(!previous||saved)return;rows=previous;previous=null;persistDraft();render();feedback('Last change undone.');});
$('save-bill').addEventListener('click',()=>{if(saved||!rows.length)return;const sale={id:billId,createdAt,rows:rows.map(r=>({...r})),payment:$('payment').value};try{const next=history.some(s=>s.id===billId)?history:[...history,sale];localStorage.setItem('bolbill-sales-v1',JSON.stringify(next));history=next;saved=true;previous=null;try{localStorage.removeItem('bolbill-draft-v1');}catch{}render();feedback('Sale saved. '+money(total(rows))+' recorded as '+sale.payment+'.');}catch{feedback('Could not save: browser storage is unavailable or full. Keep this bill open and print a copy.',true);}});
$('new-bill').addEventListener('click',()=>{if(rows.length&&!saved&&!window.confirm('Start a new bill? The current unsaved draft will be cleared.'))return;rows=[];previous=null;saved=false;billId=crypto.randomUUID();createdAt=new Date().toISOString();$('payment').value='Cash';$('command').value='';persistDraft();render();feedback('New bill ready.');});
$('print-bill').addEventListener('click',()=>{if(!rows.length){feedback('Add items before printing.',true);return;}window.print();});
render();
